const r = $input.first().json;
let opChat = '';
let opUser = '';
try {
  opChat = String($env.TELEGRAM_OPERATOR_CHAT_ID || '').trim();
  opUser = String($env.TELEGRAM_OPERATOR_USER_ID || '').trim();
} catch (e) {}

/** Grupa: CHAT_ID = -100… (gdzie lecą powiadomienia), USER_ID = Twój numeryczny from.id (@userinfobot). Prywatnie: wystarczy CHAT_ID = Twój user id; USER_ID puste. */
function senderAuthorized(fromIdRaw) {
  const fid = fromIdRaw != null ? String(fromIdRaw) : '';
  if (opUser) return fid === opUser;
  return !!opChat && fid === opChat;
}

/* --- Wiadomość / edycja (dopisek tekstowy lub głos) --- */
const msg = !r.callback_query && (r.message || r.edited_message) ? (r.message || r.edited_message) : null;
if (msg) {
  if (!senderAuthorized(msg.from && msg.from.id)) return [];
  if (!opChat) return [];
  const chatId = msg.chat && msg.chat.id != null ? msg.chat.id : null;
  if (chatId == null) return [];
  const voiceOrAudio = msg.voice || msg.audio;
  if (voiceOrAudio && voiceOrAudio.file_id) {
    return [{ json: { branch: 'voice', file_id: String(voiceOrAudio.file_id), telegram_chat_id: chatId } }];
  }
  const text = msg.text != null ? String(msg.text).trim() : '';
  if (!text || text.startsWith('/')) return [];
  return [{ json: { branch: 'append', append_text: text.slice(0, 4000), telegram_chat_id: chatId } }];
}

/* --- Callback (przyciski) --- */
const u = r.callback_query || r;
const cqid = u.id != null ? u.id : null;
if (!u || !u.data) return [{ json: { branch: 'callback', skip: true, callback_query_id: cqid, answer_text: 'Brak danych.' } }];
const data = String(u.data || '');
if (!senderAuthorized(u.from && u.from.id)) {
  return [{ json: { branch: 'callback', skip: true, callback_query_id: cqid, answer_text: 'Brak uprawnien.' } }];
}
if (!opChat) {
  return [{ json: { branch: 'callback', skip: true, callback_query_id: cqid, answer_text: 'Brak TELEGRAM_OPERATOR_CHAT_ID.' } }];
}
let action = '';
let leadId = '';
if (data.startsWith('ap:')) { action = 'approve'; leadId = data.slice(3).trim(); }
else if (data.startsWith('rj:')) { action = 'reject'; leadId = data.slice(3).trim(); }
else if (data.startsWith('snd:')) { action = 'send_offer'; leadId = data.slice(4).trim(); }
else if (data.startsWith('md:')) { action = 'modify'; leadId = data.slice(3).trim(); }
else return [{ json: { branch: 'callback', skip: true, callback_query_id: cqid, answer_text: 'Nieznana akcja.' } }];
if (!leadId || leadId.length < 32) return [{ json: { branch: 'callback', skip: true, callback_query_id: cqid, answer_text: 'Zly ID.' } }];
const opId = u.from && u.from.id != null ? u.from.id : null;
const msgChat = u.message && u.message.chat ? u.message.chat.id : null;
return [{ json: { branch: 'callback', skip: false, action, lead_id: leadId, callback_query_id: cqid, message_chat_id: msgChat, message_id: u.message && u.message.message_id, operator_telegram_user_id: opId } }];

const ing = $('Code_TelegramIngress').first().json;
const gf = $input.first().json;
const path = gf.result && gf.result.file_path ? String(gf.result.file_path) : '';
let token = '';
try {
  token = String($env.TELEGRAM_BOT_TOKEN || '').trim();
} catch (e) {}
if (!gf.ok || !path || !token) throw new Error('Telegram getFile failed');
const tg_download_url = 'https://api.telegram.org/file/bot' + token + '/' + path;
return [{ json: { telegram_chat_id: ing.telegram_chat_id, file_id: ing.file_id, tg_download_url } }];

const merge = $('Code_VoiceMergeTelegramPath').first().json;
const item = $input.first();
const bin = item.binary && item.binary.data;
let b64 = '';
if (bin && typeof bin.data === 'string' && bin.data.length) b64 = bin.data;
else if (bin && bin.data && typeof bin.data.data === 'string') b64 = bin.data.data;
if (!b64) throw new Error('Brak base64 audio po pobraniu z Telegrama (sprawdź pole binary.data w n8n).');
const hitl_pplx_voice_body = {
  model: 'sonar',
  max_tokens: 900,
  temperature: 0.3,
  messages: [
    {
      role: 'system',
      content:
        'Jesteś asystentem biura Imprezja (DJ, wesela, imprezy). Dostajesz nagranie głosowe operatora w załączniku. Odsłuchaj, zrozum intencję i odpowiedz krótko po polsku, naturalnym językiem. Bez JSON, bez markdown, bez numerowanych list. Jeśli nie możesz przetworzyć audio, poproś o wpisanie treści tekstem.',
    },
    {
      role: 'user',
      content: [
        {
          type: 'text',
          text:
            'To nagranie głosowe od operatora (Telegram). Odpowiedz na treść nagrania.',
        },
        {
          type: 'file_url',
          file_url: { url: b64 },
          file_name: 'voice.ogg',
        },
      ],
    },
  ],
};
return [{ json: { telegram_chat_id: merge.telegram_chat_id, hitl_pplx_voice_body } }];

const base = $('Code_VoiceMergeTelegramPath').first().json;
const r = $input.first().json;
let txt = '';
try {
  if (r && r.choices && r.choices[0] && r.choices[0].message) txt = String(r.choices[0].message.content || '').trim();
} catch (e) {}
txt = txt.replace(/^\`\`\`[\s\S]*?\`\`\`/g, '').trim();
if (!txt) {
  const err = r && r.error ? String(r.error.message || r.error) : '';
  txt = err
    ? 'Perplexity (audio): błąd API — ' + err.slice(0, 500) + ' — spróbuj tekstem lub sprawdź czy Sonar akceptuje ten format pliku.'
    : 'Brak odpowiedzi z Perplexity. Możliwe że API nie obsługuje tego typu audio w file_url — napisz proszę tekstem.';
}
return [{ json: { telegram_chat_id: base.telegram_chat_id, voice_reply_text: txt.slice(0, 4000) } }];

/** Skleja payload_json + ai_json z lead_queue → kształt jak po ParseAndRoute + treść maila HITL. */
const row = $('Postgres_UpdateStatus').first().json;
function pj(x) {
  if (x == null) return {};
  if (typeof x === 'object' && !Array.isArray(x)) return x;
  try { return JSON.parse(String(x)); } catch (e) { return {}; }
}
const p = pj(row.payload_json);
const ai = pj(row.ai_json);
const append = p.operator_telegram_append != null ? String(p.operator_telegram_append).trim() : '';
let body = String(ai.proposed_email_reply || '').trim();
if (!body) body = '(Brak treści Perplexity — uzupełnij ręcznie w mailu.)';
const mailFromNotify = String(p.mail_from_notify || 'Biuro Imprezja <biuro@imprezja.pl>');
const clientMail = String(p.client_to_email || p.wp_form_client_email || '').trim();
const merged = {
  ...p,
  ...ai,
  hitl_approved_body_plain: body,
  hitl_operator_instructions_for_ai: append,
  mail_from_notify: mailFromNotify,
  mail_from: mailFromNotify,
  reply_to: clientMail || mailFromNotify,
  wyslana_akcja: 'hitl_telegram_approve',
  temat_wyslanej: '',
  data_wyslania: '',
};

let hitl_bypass_offer_dedup = false;
try {
  const ing = $('Code_TelegramIngress').first().json;
  if (ing && ing.action === 'send_offer') hitl_bypass_offer_dedup = true;
} catch (e) {}
if (append.length > 0) hitl_bypass_offer_dedup = true;
merged.hitl_bypass_offer_dedup = hitl_bypass_offer_dedup;

return [{ json: merged }];

/**
 * Pełny wiersz pod arkusz **73 kolumn** (jak zapytania-imprezja-pelne-dane.csv).
 * Wejście maila + AI + kalendarz + oferta (HTML) + pola CRM. emailFrom jako czytelny tekst.
 */
const j = $input.first().json;

function emailFromStr(x) {
  if (x == null || x === '') return '';
  if (typeof x === 'string') return x;
  if (typeof x === 'object') {
    if (x.text) return String(x.text);
    if (x.address) return String(x.address);
    if (Array.isArray(x.value) && x.value[0] && x.value[0].address) return String(x.value[0].address);
  }
  return String(x);
}

function isoToPl(d) {
  if (!d || d.length < 10) return '';
  const p = d.slice(0, 10).split('-');
  if (p.length !== 3) return '';
  return p[2] + '.' + p[1] + '.' + p[0];
}

const rawStart = j.event_date_start ? String(j.event_date_start) : '';
let dataTerminIso = '';
if (rawStart.length >= 10 && /^\d{4}-\d{2}-\d{2}/.test(rawStart)) dataTerminIso = rawStart.slice(0, 10);
const rawEnd = j.event_date_end ? String(j.event_date_end) : '';
let dataTerminZakresDo = '';
if (rawEnd.length >= 10 && /^\d{4}-\d{2}-\d{2}/.test(rawEnd)) dataTerminZakresDo = rawEnd.slice(0, 10);

const bodyForShort = String(j.emailBody || j.wp_form_message || '');
const tresc = bodyForShort.length > 500 ? bodyForShort.slice(0, 500) + '…' : bodyForShort;

function boolStr(v) {
  return v === true || v === 'true' || v === 'TRUE' ? 'TRUE' : 'FALSE';
}

let workflowRun = '';
try {
  if (typeof $execution !== 'undefined' && $execution && $execution.id != null) workflowRun = String($execution.id);
} catch (e) {}

function pickRecipientEmail(j0) {
  const tryList = [j0.client_to_email, j0.email, j0.wp_form_client_email];
  for (let i = 0; i < tryList.length; i++) {
    const c = tryList[i];
    if (c && typeof c === 'string' && c.includes('@')) return c.trim();
  }
  const ef = j0.emailFrom;
  if (typeof ef === 'string') {
    const m = ef.match(/<([^>\s]+@[^>\s]+)>/);
    if (m) return m[1].trim();
    if (ef.includes('@')) return ef.trim();
    return '';
  }
  if (ef && typeof ef === 'object') {
    if (ef.address && String(ef.address).includes('@')) return String(ef.address).trim();
    if (Array.isArray(ef.value) && ef.value[0] && ef.value[0].address) return String(ef.value[0].address).trim();
    if (ef.text) {
      const t = String(ef.text);
      const m2 = t.match(/<([^>\s]+@[^>\s]+)>/);
      if (m2) return m2[1].trim();
      if (t.includes('@')) return t.trim();
    }
  }
  const _body = String(j0.emailBody || j0.wp_form_message || '');
  const _lbl = _body.match(/E-?mail\s*[:：]\s*([^\s\r\n<>]+@[^\s\r\n<>]+)/i);
  if (_lbl) return _lbl[1].trim();
  const _any = _body.match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i);
  if (_any) return _any[0].trim();
  return '';
}

let telefon = String(j.wp_form_phone || '').trim();
if (!telefon) {
  const pl = bodyForShort.match(/(?:Telefon|tel\.?|kom\.?|phone)\s*[:：]\s*([+\d\s\-().]{8,40})/i);
  if (pl) telefon = pl[1].replace(/\s+/g, ' ').trim();
}

const resend_to = pickRecipientEmail(j);
let automail_skip_duplicate_offer_send = false;
let automail_skip_duplicate_offer_reason = '';
try {
  const staticData = $getWorkflowStaticData('global');
  if (!staticData.automailOfferDedup) staticData.automailOfferDedup = {};
  const emailK = String(resend_to || '').trim().toLowerCase();
  const wa = String(j.wyslana_akcja || 'single_date');
  const rk = (dataTerminIso || '').slice(0, 10) + '_' + (dataTerminZakresDo || '').slice(0, 10);
  const appendFp = String(j.operator_telegram_append || '').trim().slice(0, 120);
  const dedupKey = emailK + '|' + wa + '|' + rk + '|' + appendFp;
  const WINDOW_MS = 20 * 60 * 1000;
  const now = Date.now();
  const prev = staticData.automailOfferDedup[dedupKey];
  if (emailK.includes('@') && !j.hitl_bypass_offer_dedup) {
    if (prev != null && now - prev < WINDOW_MS) {
      automail_skip_duplicate_offer_send = true;
      automail_skip_duplicate_offer_reason = 'duplicate_within_20m_same_client_dates';
    } else {
      staticData.automailOfferDedup[dedupKey] = now;
    }
  }
} catch (e) {
  automail_skip_duplicate_offer_reason = 'dedup_err';
}
const emailFromReadable = emailFromStr(j.emailFrom);
const zapisano_at = new Date().toISOString();

function escapeHtmlFollowup(s) {
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;');
}
function terminPhraseFollowup(j0, isoStart, zakresDoIso) {
  const wa = String(j0.wyslana_akcja || '');
  if (wa === 'range_calendar_days') {
    const a = isoToPl(isoStart) || (String(j0.event_date_start || '').slice(0, 10));
    const b = isoToPl(zakresDoIso) || (String(j0.event_date_end || '').slice(0, 10));
    if (a && b) return 'okres ' + a + '–' + b;
    if (a) return 'okres wokół ' + a;
    return 'okres z zapytania';
  }
  const pl = isoToPl(isoStart);
  if (pl) return pl;
  return 'termin z zapytania';
}
const followupHasEmail = !!(resend_to && String(resend_to).includes('@'));
const followupCandidate = j.skip_client_offer_resend !== true && j.human !== true && followupHasEmail && j.is_event_inquiry === true;
let followup_eligible_at = '';
let followup_offer_variant = 'none';
let subject_followup_3d = '';
let html_followup_3d = '';
if (followupCandidate) {
  const eligible = new Date();
  let delayH = 48;
  try {
    const eh = String($env.FOLLOWUP_DELAY_HOURS ?? '').trim();
    if (eh !== '') {
      const n0 = parseInt(eh, 10);
      if (Number.isFinite(n0) && n0 >= 0) delayH = n0;
    } else {
      const ed = String($env.FOLLOWUP_DELAY_DAYS ?? '').trim();
      if (ed !== '') {
        const d0 = parseInt(ed, 10);
        if (Number.isFinite(d0) && d0 >= 0) delayH = d0 * 24;
      }
    }
  } catch (e) {}
  eligible.setUTCHours(eligible.getUTCHours() + delayH);
  followup_eligible_at = eligible.toISOString();
  const wa = String(j.wyslana_akcja || '');
  if (wa === 'range_calendar_days') followup_offer_variant = 'range_list';
  else if (j.demo_termin_wolny === true) followup_offer_variant = 'termin_wolny';
  else followup_offer_variant = 'termin_zajety';
  const datePhrase = terminPhraseFollowup(j, dataTerminIso, dataTerminZakresDo);
  const cn = (j.client_name || j.wp_form_name || '').trim();
  const greeting = cn ? ('Cześć ' + escapeHtmlFollowup(cn) + ',') : 'Cześć,';
  let terminNote = '';
  if (followup_offer_variant === 'termin_wolny' || followup_offer_variant === 'range_list') {
    terminNote = '<p>W kontekście <strong>' + escapeHtmlFollowup(datePhrase) + '</strong> kalendarz nadal wygląda na <strong>wolny</strong> — chętnie potwierdzę ostatecznie po Twojej decyzji.</p>';
  } else {
    terminNote = '<p>Wracam do <strong>oferty i propozycji innych terminów</strong>, o których pisałem wcześniej.</p>';
  }
  subject_followup_3d = 'Co słychać z zapytaniem o termin? 🙂 Krótka chwila na ofertę';
  html_followup_3d =
    '<div style="font-family:Segoe UI,Arial,sans-serif;font-size:15px;line-height:1.5;color:#222;">' +
    '<p>' + greeting + '</p>' +
    '<p>mam nadzieję, że u Was wszystko OK i że przygotowania do <strong>imprezy</strong> idą w dobrym kierunku — niezależnie czy mowa o <strong>weselu</strong>, osiemnastce, urodzinach, firmówce czy innej okazji 🙂</p>' +
    '<p>Wracam z krótkim przypomnieniem po mojej wiadomości z ofertą w sprawie <strong>' + escapeHtmlFollowup(datePhrase) + '</strong>.</p>' +
    terminNote +
    '<p>Chciałem się odezwać i zapytać wprost:</p>' +
    '<ul style="margin:0 0 1em 1.2em;">' +
    '<li>czy <strong>oferta i koncepcja imprezy</strong> są w Waszym stylu?</li>' +
    '<li>czy są pytania co do <strong>muzyki, atrakcji</strong> (taniec w chmurach, fotobudka, fontanny iskier itd.) albo <strong>szczegółów</strong>?</li>' +
    '</ul>' +
    '<p>Zapraszam do obejrzenia <strong>realizacji</strong>:</p>' +
    '<ul style="margin:0 0 1em 1.2em;">' +
    '<li><strong>Facebook:</strong> <a href="https://www.facebook.com/imprezjadamiannowaczyk">facebook.com/imprezjadamiannowaczyk</a> — relacje i opinie</li>' +
    '<li><strong>Instagram:</strong> <a href="https://www.instagram.com/imprezja/">instagram.com/imprezja</a> — stories z imprez i efekty specjalne</li>' +
    '</ul>' +
    '<p><strong>Dajcie znać</strong>, co myślicie — <strong>503 836 965</strong>, odpowiedź na tego maila albo krótka rozmowa online. Chętnie doprecyzuję szczegóły 🙂</p>' +
    '<p>Pozdrawiam serdecznie,<br><strong>Damian Nowaczyk</strong><br>DJ / wodzirej Imprezja<br><a href="https://www.imprezja.pl">www.imprezja.pl</a></p></div>';
}

const gca = j.google_calendar_available;
let googleCalendarAvailableCell = '';
if (typeof gca === 'boolean') googleCalendarAvailableCell = boolStr(gca);
else if (gca != null && gca !== '') googleCalendarAvailableCell = String(gca);

const fullSheet = {
  zapisano_at,
  workflow_run: workflowRun,
  emailSubject: String(j.emailSubject || ''),
  emailBody: String(j.emailBody || ''),
  emailFrom: emailFromReadable,
  mailDate: String(j.mailDate || ''),
  wp_form_name: String(j.wp_form_name || ''),
  wp_form_phone: String(j.wp_form_phone || ''),
  wp_form_message: String(j.wp_form_message || ''),
  wp_form_client_email: String(j.wp_form_client_email || ''),
  is_event_inquiry: boolStr(j.is_event_inquiry === true),
  event_inquiry_confidence: String(j.event_inquiry_confidence || 'low'),
  needs_human_review: boolStr(j.needs_human_review === true),
  event_date_start: j.event_date_start != null && j.event_date_start !== '' ? String(j.event_date_start) : '',
  event_date_end: j.event_date_end != null && j.event_date_end !== '' ? String(j.event_date_end) : '',
  date_confidence: String(j.date_confidence || 'low'),
  venue_or_city: j.venue_or_city != null ? String(j.venue_or_city) : '',
  location_confidence: String(j.location_confidence || 'low'),
  client_name: String(j.client_name || ''),
  event_kind: String(j.event_kind || ''),
  raw_quote: String(j.raw_quote || ''),
  date_ok: boolStr(j.date_ok === true),
  location_ok: boolStr(j.location_ok === true),
  human: boolStr(j.human === true),
  dj_notify_email: String(j.dj_notify_email || ''),
  mail_from_notify: String(j.mail_from_notify || ''),
  client_to_email: String(j.client_to_email || ''),
  calStart: j.calStart != null && j.calStart !== '' ? String(j.calStart) : '',
  calEnd: j.calEnd != null && j.calEnd !== '' ? String(j.calEnd) : '',
  check_date_ymd: j.check_date_ymd != null && j.check_date_ymd !== '' ? String(j.check_date_ymd) : '',
  calendar_query_until_exclusive: j.calendar_query_until_exclusive != null && j.calendar_query_until_exclusive !== '' ? String(j.calendar_query_until_exclusive) : '',
  calendar_check_note: j.calendar_check_note != null ? String(j.calendar_check_note) : '',
  demo_termin_wolny: boolStr(j.demo_termin_wolny === true),
  google_calendar_available: googleCalendarAvailableCell,
  google_calendar_warning: String(j.google_calendar_warning || ''),
  event_kind_used: String(j.event_kind_used || j.event_kind || 'other'),
  mail_from: String(j.mail_from || ''),
  reply_to: String(j.reply_to || ''),
  offer_pdf_url: String(j.offer_pdf_url || ''),
  subject_wolny: String(j.subject_wolny || ''),
  subject_zajety: String(j.subject_zajety || ''),
  html_wolny: String(j.html_wolny || ''),
  html_zajety: String(j.html_zajety || ''),
  resend_to,
  data_termin_iso: dataTerminIso,
  data_termin_pl: isoToPl(dataTerminIso),
  data_termin_zakres_do: dataTerminZakresDo,
  typ_imprezy: String(j.event_kind_used || j.event_kind || 'other'),
  klient_imie: String(j.client_name || j.wp_form_name || ''),
  email: String(j.client_to_email || ''),
  telefon,
  miejscowosc: j.venue_or_city != null ? String(j.venue_or_city) : '',
  pewnosc_daty: String(j.date_confidence || 'low'),
  pewnosc_lokalizacji: String(j.location_confidence || 'low'),
  zapytanie_o_impreze: boolStr(j.is_event_inquiry === true),
  reczna_obsluga: boolStr(j.human === true),
  lokalizacja_ok: boolStr(j.location_ok === true),
  kalendarz_wolny: boolStr(j.demo_termin_wolny === true),
  notatka_kalendarz: j.calendar_check_note != null ? String(j.calendar_check_note) : '',
  temat_maila: String(j.emailSubject || ''),
  nadawca_naglowek: emailFromReadable,
  tresc_skrocona: tresc.replace(/\r?\n/g, ' '),
  wyslana_akcja: String(j.wyslana_akcja || ''),
  temat_wyslanej: String(j.temat_wyslanej || ''),
  data_wyslania: String(j.data_wyslania || ''),
  ask_clarification_source: String(j.ask_clarification_source || ''),
  followup_candidate: boolStr(followupCandidate),
  followup_eligible_at: followup_eligible_at || '',
  followup_sent: 'FALSE',
  followup_sent_at: '',
  followup_offer_variant: followup_offer_variant || 'none',
  subject_followup_3d: subject_followup_3d || '',
  html_followup_3d: html_followup_3d || '',
};

const skipOfferOnly = j.skip_client_offer_resend === true || j.skip_client_offer_resend === 'true' || String(j.skip_client_offer_resend || '').toUpperCase() === 'TRUE';
return [{ json: { ...j, ...fullSheet, skip_client_offer_resend: skipOfferOnly, automail_skip_duplicate_offer_send, automail_skip_duplicate_offer_reason } }];

/**
 * Wszystkie **73 kolumn** jak w zapytania-imprezja-pelne-dane.csv (kolejność = nagłówek arkusza).
